# Define the helper functions directly since we can't import them
def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple implementation for demonstration
    # In practice, this would find the smallest substring that needs changing
    if s_in == s_out:
        return None

    # For now, let's just return the first difference
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If prefixes match, check length difference
    if len(s_in) < len(s_out):
        return (s_in[-1], s_out[len(s_in):], len(s_in)-1) if len(s_in) > 0 else (None, s_out[len(s_in):], 0)
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out):], s_out[-1], len(s_out)-1) if len(s_out) > 0 else (s_in[len(s_out):], None, 0)

    return (None, None, -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates based on the change from s_in to s_out."""
    # Simple implementation - in real case this would be more sophisticated
    edit = find_minimal_edit(s_in, s_out)
    if edit is None:
        return []

    old_sub, new_sub, pos = edit
    if old_sub is None:
        return []

    # Return the simple rule that changes this character
    return [(old_sub, new_sub)]

def apply_rules(strings, rules):
    """Apply a sequence of rules to a list of strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules transform inputs to outputs."""
    transformed = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(transformed, outputs) if i == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find examples where rules incorrectly modify strings that should be unchanged."""
    transformed = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, trans) in enumerate(zip(inputs, outputs, transformed)):
        if inp != outp and trans != outp:
            over_apps.append((i, inp, trans))
    return over_apps

# Now let's analyze our specific problem
inputs = ['zui', 'yyi', 'gfbiu', 'bbfzki', 'xbxju']
outputs = ['zui', 'yyi', 'gfbiu', 'bbfzzcyi', 'zcabzcaju']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, inp, outp in changed:
    print(f"  {idx}: '{inp}' -> '{outp}'")

print("\nAnalyzing each change:")
for idx, inp, outp in changed:
    print(f"Input: '{inp}', Output: '{outp}'")

